python3 - <<'PY'
import urllib.request, json
crates=['anyhow','async-trait','image','log','prost','tokio','data-encoding','tar','tokio-util','futures-util','internet-packet','pyo3-log','pyo3','pyo3-asyncio','smoltcp','windows','nix','apple-security-framework','env_logger']
for c in crates:
    try:
        with urllib.request.urlopen(f'https://crates.io/api/v1/crates/{c}', timeout=20) as r:
            data=json.load(r)
        print('\n',c)
        for v in data['versions'][:20]:
            print(v['num'], v['created_at'][:10], 'rust', v.get('rust_version'))
    except Exception as e:
        print('ERR', c, e)
PY

